/**
 * Unit tests for NamespaceResolver.isSealed()
 */
public class NamespaceResolver_isSealed_TriageGen2Test {







    @Test
    public void testIsSealed_MultipleSealCalls_ReturnsTrue() {
        // Calling seal() multiple times should still result in isSealed() being true
        NamespaceResolver resolver = new NamespaceResolver();

        resolver.seal();
        resolver.seal();

        assertTrue("isSealed() should remain true after multiple seal() calls", resolver.isSealed());
    }
